     1→import { useAtomValue, useSetAtom } from "jotai";
     2→import { MatrixService } from "modules/matrix-client/services";
     3→import { NavigationContainerRef } from "modules/navigation/const";
     4→import { type FC, useEffect } from "react";
     5→import Toast from "react-native-toast-message";
