   895→  /** Check if a direct room exists with a user */
   896→  public static getExistingDirectRoom = async (
   897→    userId: string,
   898→  ): Promise<string | null> => {
   899→    if (!this.instance) throw new Error("Client not initialized");
   900→
   901→    try {
   902→      const rooms = this.instance.rooms();
   903→      for (const room of rooms) {
   904→        const roomInfo = await room.roomInfo();
   905→        if (roomInfo?.isDirect) {
   906→          const members = await room.members();
   907→          const memberList = members.nextChunk(100000) ?? [];
   908→          const hasUser = memberList.some((member) => member.userId === userId);
   909→          if (hasUser) return room.id();
   910→        }
   911→      }
   912→      return null;
   913→    } catch (error) {
   914→      console.error("Failed to check for existing direct room:", error);
   915→      return null;
   916→    }
   917→  };
