   960→  ): Promise<string> => {
   961→    try {
   962→      const roomOptions: CreateRoomParameters = {
   963→        name: roomName,
   964→        topic: roomTopic,
   965→        preset:
   966→          type === "private" ? RoomPreset.PrivateChat : RoomPreset.PublicChat,
