  1385→  /** Subscribe to backup state changes */
  1386→  public static subscribeToBackupState = (
  1387→    callback: (state: MappedBackupState) => void,
  1388→  ): TaskHandleInterface => {
  1389→    if (!this.instance) throw new Error("Client not initialized");
  1390→    return this.instance.encryption().backupStateListener({
  1391→      onUpdate: async (state: BackupState) => {
  1392→        if (state === BackupState.Unknown) {
  1393→          if (!this.instance) throw new Error("Client not initialized");
  1394→          const backupExists = await this.instance
  1395→            .encryption()
  1396→            .backupExistsOnServer();
  1397→
  1398→          if (backupExists) callback("enabled");
  1399→          else callback("unknown");
  1400→          return;
  1401→        }
  1402→        callback(mapBackupState(state));
  1403→      },
  1404→    });
  1405→  };
