  1430→  /** Set up verification listeners - call this after login to enable verification */
  1431→  public static setupVerification = async (
  1432→    onRequest: VerificationRequestCallback,
  1433→    onEmojis: VerificationEmojisCallback,
  1434→    onStateChange: VerificationStateChangeCallback,
  1435→  ) => {
  1436→    if (!this.instance) throw new Error("Client not initialized");
  1437→
  1438→    // Store callbacks
  1439→    this.onVerificationRequest = onRequest;
  1440→    this.onVerificationEmojis = onEmojis;
  1441→    this.onVerificationStateChange = onStateChange;
  1442→
  1443→    // Get verification controller
  1444→    this.verificationController =
  1445→      await this.instance.getSessionVerificationController();
  1446→
  1447→    // Create delegate to handle verification events
  1448→    const delegate: SessionVerificationControllerDelegate = {
  1449→      didReceiveVerificationRequest: (
  1450→        details: SessionVerificationRequestDetails,
  1451→      ) => {
  1452→        console.log("📩 Verification request received:", details);
  1453→        this.onVerificationStateChange?.("request");
  1454→        this.onVerificationRequest?.(details);
  1455→      },
  1456→
  1457→      didAcceptVerificationRequest: () => {
  1458→        console.log("✅ Verification request accepted");
  1459→        this.onVerificationStateChange?.("accepted");
  1460→      },
  1461→
  1462→      didStartSasVerification: () => {
  1463→        console.log("🔐 SAS verification started");
  1464→        this.onVerificationStateChange?.("sasStarted");
  1465→      },
  1466→
  1467→      didReceiveVerificationData: (data: SessionVerificationData) => {
  1468→        console.log("📊 Verification data received:", data);
  1469→
  1470→        if (data.tag === SessionVerificationData_Tags.Emojis) {
  1471→          const emojis = data.inner.emojis.map((emoji) => ({
  1472→            symbol: emoji.symbol(),
  1473→            description: emoji.description(),
  1474→          }));
  1475→          console.log("🎭 Emojis:", emojis);
  1476→          this.onVerificationStateChange?.("emojis");
  1477→          this.onVerificationEmojis?.(emojis);
  1478→        } else if (data.tag === SessionVerificationData_Tags.Decimals) {
  1479→          console.log("🔢 Decimals:", data.inner.values);
  1480→        }
  1481→      },
  1482→
  1483→      didFail: () => {
  1484→        console.log("❌ Verification failed");
  1485→        this.onVerificationStateChange?.("failed");
  1486→      },
  1487→
  1488→      didCancel: () => {
  1489→        console.log("🚫 Verification cancelled");
  1490→        this.onVerificationStateChange?.("cancelled");
  1491→      },
  1492→
  1493→      didFinish: () => {
  1494→        console.log("🎉 Verification finished successfully!");
  1495→        this.onVerificationStateChange?.("success");
  1496→      },
  1497→    };
  1498→
  1499→    // Set the delegate
  1500→    this.verificationController.setDelegate(delegate);
  1501→    console.log("✅ Verification controller set up successfully");
  1502→  };
