### 2c. `src/modules/matrix-client/services/matrix-service.ts`

Add three new public static methods:

```typescript
/** Pin a user's identity to trust their current key */
public static pinUserIdentity = async (userId: string): Promise<void> => {
  if (!this.instance) throw new Error("Client not initialized");
  const encryption = this.instance.encryption();
  const userIdentity = await encryption.userIdentity(userId, true);
  if (!userIdentity) throw new Error("User identity not found");
  await userIdentity.pin();
};

/** Withdraw verification from a user and resend pending events in the room */
public static withdrawVerificationAndResend = async (
  roomId: string,
  userIds: string[],
): Promise<void> => {
  if (!this.instance) throw new Error("Client not initialized");
  const room = this.instance.getRoom(roomId);
  if (!room) throw new Error("Room not found");
  const timeline = await room.timeline();
  if (!timeline) throw new Error("Timeline not found");
  // sendHandle is the timeline itself — it acts as the send handle for resending
  await room.withdrawVerificationAndResend(userIds, timeline);
};

/** Get identity violation state for a user */
public static getUserIdentityState = async (
  userId: string,
): Promise<{
  hasViolation: boolean;
  isVerified: boolean;
  wasPreviouslyVerified: boolean;
} | null> => {
  if (!this.instance) return null;
  try {
    const encryption = this.instance.encryption();
    const userIdentity = await encryption.userIdentity(userId, false);
    if (!userIdentity) return null;
    return {
      hasViolation: userIdentity.hasVerificationViolation(),
      isVerified: userIdentity.isVerified(),
      wasPreviouslyVerified: userIdentity.wasPreviouslyVerified(),
    };
  } catch {
    return null;
  }
};
```

**Note on `withdrawVerificationAndResend` signature:** The SDK method is `room.withdrawVerificationAndResend(userIds, sendHandle)`. From the codebase, `sendHandle` is the live `timeline` object obtained from `room.timeline()`. Verify the exact expected type from the SDK's TypeScript definitions before implementing.

